public static class Store {
 public static string Root=>Environment.GetEnvironmentVariable("DIAGSCOPE_DATA_ROOT")??Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),"DiagScope2-Review20261110","Data");
 public static JsonSerializerOptions Options=new(){WriteIndented=true};
 public static string SessionPath(Study s){if(!Regex.IsMatch(s.Id,"^[a-fA-F0-9]{32}$"))throw new InvalidDataException("Nieprawidłowy identyfikator badania.");return Path.Combine(Root,"Sessions",s.Id+".json");}
 public static void WriteAtomic(string path,string text) => WriteAtomic(path, new UTF8Encoding(false).GetBytes(text));
 public static void WriteAtomic(string path,byte[] bytes) {
  path=Path.GetFullPath(path);Directory.CreateDirectory(Path.GetDirectoryName(path)!);
  string temp=path+"."+Guid.NewGuid().ToString("N")+".tmp";
  try {
   using(var stream=new FileStream(temp,FileMode.CreateNew,FileAccess.Write,FileShare.None)) {
    stream.Write(bytes);stream.Flush(true);
   }
   if(File.Exists(path))File.Replace(temp,path,path+".bak");else File.Move(temp,path);
  }finally{if(File.Exists(temp))File.Delete(temp);}
 } public static void Save(Study s){WriteAtomic(SessionPath(s),JsonSerializer.Serialize(s,Options));WriteAtomic(Path.Combine(Root,"active.txt"),s.Id);}
 public static Study Load(string path){var s=JsonSerializer.Deserialize<Study>(File.ReadAllText(path))??throw new InvalidDataException("Pusty plik badania.");if(s.Schema!="DiagScope2-native-1"||!Regex.IsMatch(s.Id,"^[a-fA-F0-9]{32}$")||s.Vehicle==null||s.Logs==null||s.Entries==null||s.Dtcs==null||s.Checks==null||s.AutoScans==null)throw new InvalidDataException("Nieprawidłowy format badania.");foreach(var log in s.Logs)LogMetadata.ApplyVerifiedLabels(log);return s;}
 public static Study Startup(){string p=Path.Combine(Root,"active.txt");if(!File.Exists(p))return new();string id=File.ReadAllText(p).Trim();if(!Regex.IsMatch(id,"^[a-fA-F0-9]{32}$"))throw new InvalidDataException("Nieprawidłowy identyfikator ostatniego badania.");return Load(Path.Combine(Root,"Sessions",id+".json"));}
 public static void PreserveSource(LogData l,Study s){string vehicle=string.IsNullOrWhiteSpace(s.Vehicle.Vin)?s.Id:Regex.Replace(s.Vehicle.Vin,"[^A-Za-z0-9]","");string dir=Path.Combine(Root,"Vehicles",vehicle,"Logs");Directory.CreateDirectory(dir);string dest=Path.Combine(dir,LogMetadata.FileStem(l)+"_"+l.Id+Path.GetExtension(l.OriginalPath));byte[] bytes=Importer.ReadBytes(l.OriginalPath);string hash=Convert.ToHexString(System.Security.Cryptography.SHA256.HashData(bytes));if(l.Hash.Length>0&&l.Hash!=hash)throw new IOException("Plik zmienił się po odczycie. Zatrzymaj zapis i zaimportuj ponownie.");using(var file=new FileStream(dest,FileMode.CreateNew,FileAccess.Write,FileShare.Read)){file.Write(bytes);file.Flush(true);}l.Hash=hash;l.StoredFile=dest;}
}
public record Gap(int Row,double Start,double End,double Duration);
public class Quality {public int InvalidTime,Missing,Reverse,Duplicate;public double Median;public List<Gap> Gaps=[];public override string ToString()=>$"mediana Δt {Median:F3} s · luki {Gaps.Count} · brak czasu {InvalidTime} · cofnięcia {Reverse} · duplikaty {Duplicate} · braki wartości {Missing}";}
public static class Analyzer {
 public static Quality Analyze(Channel c){var q=new Quality();var intervals=new List<double>();for(int i=0;i<c.Samples.Count;i++){var p=c.Samples[i];if(!p.Time.HasValue)q.InvalidTime++;if(string.IsNullOrWhiteSpace(p.Raw))q.Missing++;if(i==0||!p.Time.HasValue||!c.Samples[i-1].Time.HasValue)continue;double d=p.Time.Value-c.Samples[i-1].Time!.Value;if(d>0)intervals.Add(d);else if(d==0)q.Duplicate++;else q.Reverse++;}intervals.Sort();q.Median=intervals.Count>0?intervals[intervals.Count/2]:0;for(int i=1;i<c.Samples.Count;i++){var a=c.Samples[i-1];var b=c.Samples[i];if(a.Time.HasValue&&b.Time.HasValue&&q.Median>0&&b.Time-a.Time>3*q.Median)q.Gaps.Add(new(b.Row,a.Time.Value,b.Time.Value,b.Time.Value-a.Time.Value));}return q;}
 public static string Summary(LogData log)=>string.Join("\n",log.Channels.Select(c=>$"{c.Name} [{c.Unit}] ({c.Clock}): {Analyze(c)}"))+"\n\n"+string.Join("\n",log.Warnings)+"\nPrzerwa w zapisie nie dowodzi utraty danych ECU ani uszkodzenia części.";
}
public static partial class Importer {
 public static double? Number(string s)=>double.TryParse(s.Trim().Replace(',','.'),NumberStyles.Float,CultureInfo.InvariantCulture,out var n)&&double.IsFinite(n)?n:null;
 public static double? Time(string s){if(s.Contains(':')&&!s.Contains('T')){double total=0;foreach(var part in s.Split(':')){var n=Number(part);if(!n.HasValue)return null;total=total*60+n.Value;}return total;}return Number(s);}
 public static byte[] ReadBytes(string path) {
  using var f=new FileStream(path,FileMode.Open,FileAccess.Read,FileShare.ReadWrite|FileShare.Delete);
  if(f.Length>100_000_000)throw new InvalidDataException("Plik przekracza 100 MB.");
  using var m=new MemoryStream();byte[] buffer=new byte[65536];int n;
  while((n=f.Read(buffer))>0){if(m.Length+n>100_000_000)throw new InvalidDataException("Plik przekracza 100 MB.");m.Write(buffer,0,n);}return m.ToArray();
 }
 public static string Decode(byte[] bytes){try{return new UTF8Encoding(false,true).GetString(bytes).TrimStart('\uFEFF');}catch(DecoderFallbackException){Encoding.RegisterProvider(CodePagesEncodingProvider.Instance);return Encoding.GetEncoding(1250).GetString(bytes);}}
 public static string ReadText(string path)=>Decode(ReadBytes(path)); public static List<string[]> Csv(string text,char sep){var rows=new List<string[]>();var row=new List<string>();var v=new StringBuilder();bool quoted=false;for(int i=0;i<text.Length;i++){char c=text[i];if(c=='"'){if(quoted&&i+1<text.Length&&text[i+1]=='"'){v.Append('"');i++;}else quoted=!quoted;}else if(c==sep&&!quoted){row.Add(v.ToString());v.Clear();}else if((c=='\n'||c=='\r')&&!quoted){if(c=='\r'&&i+1<text.Length&&text[i+1]=='\n')i++;row.Add(v.ToString());rows.Add(row.ToArray());row.Clear();v.Clear();}else v.Append(c);}if(quoted)throw new FormatException("Niepełne pole CSV w cudzysłowie.");if(v.Length>0||row.Count>0){row.Add(v.ToString());rows.Add(row.ToArray());}return rows;}
 public static string Cell(string[] r,int i)=>i>=0&&i<r.Length?r[i].Trim():"";
 public static char Separator(string text){var first=text.Split('\n').Take(20);return new[]{',',';','\t'}.OrderByDescending(c=>first.Max(l=>Csv(l,c).FirstOrDefault()?.Length??0)).First();}
 public static LogData Read(string path){byte[] bytes=ReadBytes(path);string text=Decode(bytes);var l=path.EndsWith(".jsonl",StringComparison.OrdinalIgnoreCase)?JsonLines(text):path.EndsWith(".json",StringComparison.OrdinalIgnoreCase)?JsonSerializer.Deserialize<LogData>(text)??throw new FormatException("Nieprawidłowy log JSON."):Vcds(text);if(l.Channels==null||!l.Channels.Any(c=>c.Samples.Count>0))throw new FormatException("Brak kanałów w logu.");l.Name=Path.GetFileName(path);l.OriginalPath=path;LogMetadata.ApplyNames(l);l.Hash=Convert.ToHexString(System.Security.Cryptography.SHA256.HashData(bytes));return l;}
 public static LogData Vcds(string text){var rows=Csv(text,Separator(text));var l=new LogData{Source="VCDS CSV"};LogMetadata.ReadVcdsHeader(l,rows);int sessions=0;
 for(int h=0;h<rows.Count;h++){int[] stamps=rows[h].Select((s,i)=>(s,i)).Where(x=>x.s.Trim().Equals("STAMP",StringComparison.OrdinalIgnoreCase)).Select(x=>x.i).ToArray();if(stamps.Length==0)continue;sessions++;int g=-1;for(int j=h-1;j>=Math.Max(0,h-5);j--)if(rows[j].Any(c=>Regex.IsMatch(c,@"Group\s*[A-Z]:|Grupa\s*[A-Z]:",RegexOptions.IgnoreCase))){g=j;break;}var mapping=new List<(Channel c,int col,int time)>();
 foreach(int stamp in stamps){int end=stamps.Where(x=>x>stamp).DefaultIfEmpty(rows[h].Length).Min();string group=g>=0?Cell(rows[g],stamp+1).TrimStart('\''):"";for(int col=stamp+1;col<end;col++){string unit=Cell(rows[h],col),name=g>=0?Cell(rows[Math.Min(g+1,h)],col):Cell(rows[Math.Max(0,h-2)],col);string extra=g>=0&&g+2<h?Cell(rows[g+2],col):"";if(name.Length==0&&unit.Length==0&&extra.Length==0)continue;string address=group.Length>0?$"{group}.{col-stamp}":$"kolumna {col+1}";string label=string.Join(" · ",new[]{name,extra}.Where(n=>n.Length>0));var c=new Channel{Name=label.Length>0?label:"Kanał bez opisu",OriginalName=label,Address=address,Key=group.Length>0?"VCDS:"+address:"",Unit=unit,Clock=$"sesja {sessions}, STAMP {stamp+1}",TextState=unit.Contains("bit",StringComparison.OrdinalIgnoreCase)||name.Contains("bit",StringComparison.OrdinalIgnoreCase)};l.Channels.Add(c);mapping.Add((c,col,stamp));}}
 int row=h+1;for(;row<rows.Count;row++){if(rows[row].Any(c=>c.Trim().Equals("STAMP",StringComparison.OrdinalIgnoreCase)||Regex.IsMatch(c,@"Group\s*[A-Z]:|Grupa\s*[A-Z]:",RegexOptions.IgnoreCase)))break;if(rows[row].All(string.IsNullOrWhiteSpace))continue;if(!mapping.Any(m=>Time(Cell(rows[row],m.time)).HasValue)){l.Warnings.Add($"Wiersz {row+1}: brak rozpoznanego czasu; zachowano braki w przebiegach.");}l.Rows++;foreach(var (c,col,t) in mapping){string raw=Cell(rows[row],col);c.Samples.Add(new(){Time=Time(Cell(rows[row],t)),Value=c.TextState?null:Number(raw),Raw=raw,Row=row+1});if(raw.Length>0&&!Number(raw).HasValue)c.TextState=true;}}h=row-1;
 }
 if(l.Channels.Count==0||!l.Channels.Any(c=>c.Samples.Any(s=>s.Time.HasValue)))throw new FormatException("Nie rozpoznano nagłówka VCDS STAMP. Użyj importu CSV z wyborem kolumn.");if(sessions>1)l.Warnings.Add($"Plik zawiera {sessions} sesji. Zachowano je jako osobne przebiegi i zegary.");foreach(var c in l.Channels.Where(c=>c.Unit.Length==0))l.Warnings.Add($"Brak jednostki: {c.Name}.");return l;}
 public static LogData Mapped(string text,char sep,int header,int start,int timeCol,IEnumerable<(int Col,string Unit)> selected,string source){var rows=Csv(text,sep);if(header<0||start<=header||start>=rows.Count)throw new FormatException("Nieprawidłowy zakres wierszy.");var l=new LogData{Source=source};foreach(var spec in selected){var c=new Channel{Name=Cell(rows[header],spec.Col),Unit=spec.Unit,Clock=$"kolumna czasu {timeCol+1}"};for(int i=start;i<rows.Count;i++){if(rows[i].All(string.IsNullOrWhiteSpace))continue;string raw=Cell(rows[i],spec.Col);c.Samples.Add(new(){Time=Time(Cell(rows[i],timeCol)),Value=Number(raw),Raw=raw,Row=i+1});}c.TextState=c.Unit.Contains("bit",StringComparison.OrdinalIgnoreCase)||c.Samples.Any(p=>p.Raw.Length>0&&!p.Value.HasValue);l.Channels.Add(c);}l.Rows=l.Channels.FirstOrDefault()?.Samples.Count??0;if(l.Rows==0||!l.Channels.Any(c=>c.Samples.Any(p=>p.Time.HasValue)))throw new FormatException("Brak odczytów z prawidłowym czasem.");return l;}
 public static LogData JsonLines(string text)=>JsonLogReader.Read(text);
}